attribute "tsugumi";
namespace protein;
table PdbFiles { value:string; }
table Outputs { data:PdbFiles (required, tsugumi: "directory"); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
    packages = ps: [ ps.certifi ];
  };
}

